def transferer_donnees(apps, schema_editor):
    """Copie les profils en conservant leurs identifiants."""

    AncienProfil = apps.get_model("oc_lettings_site", "Profile")
    NouveauProfil = apps.get_model("profiles", "Profile")

    database = schema_editor.connection.alias

    # ==================================================
    # VÉRIFICATION DE LA TABLE DE DESTINATION
    # ==================================================

    if NouveauProfil.objects.using(database).exists():
        raise RuntimeError("La table de destination n'est pas vide.")

    # ==================================================
    # TRANSFERT DES PROFILS
    # ==================================================

    for profil in AncienProfil.objects.using(database).all():
        NouveauProfil.objects.using(database).create(
            id=profil.id,
            user_id=profil.user_id,
            favorite_city=profil.favorite_city,
        )

    # ==================================================
    # VÉRIFICATION DU TRANSFERT
    # ==================================================

    if (
        AncienProfil.objects.using(database).count()
        != NouveauProfil.objects.using(database).count()
    ):
        raise RuntimeError("Le transfert des profils est incomplet.")


